        S3Object s3Object = s3.getObject(getObject);

        InputStream content = s3Object.getObjectContent();

        Files.copy(content, dst, StandardCopyOption.REPLACE_EXISTING);

        s3Object.getObjectContent().close();

        return dst;
    }
}
